export function getChecklist(slug: string): TravelChecklist | undefined {
  return TRAVEL_CHECKLISTS.find((c) => c.slug === slug);
}

export const CHECKLIST_SLUGS = TRAVEL_CHECKLISTS.map((c) => c.slug);
